const lerp = (a: number, b: number, u: number) => a + (b - a) * u;
const mix = (a: number[], b: number[], u: number) => a.map((v, i) => lerp(v, b[i] ?? v, u));

/** Pose for a turn t in [-1, 1]: -1 left, 0 front, +1 right. */
export function poseAt(t: number): Pose {
  const to = t < 0 ? LEFT : RIGHT;
  const u = Math.min(1, Math.abs(t));
  return {
    body: mix(FRONT.body, to.body, u),
    top: mix(FRONT.top, to.top, u),
    side: mix(FRONT.side, to.side, u),
    sideRight: mix(FRONT.sideRight, to.sideRight, u),
    antennas: FRONT.antennas.map((a, i) => mix(a, to.antennas[i] ?? a, u)),
    eyes: FRONT.eyes.map((e, i) => mix(e, to.eyes[i] ?? e, u)),
  };
}

/** Fills a path template with numbers, in order. */
export function pathFrom(template: string, values: number[]): string {
  let i = 0;
  return template.replace(/#/g, () => (values[i++] ?? 0).toFixed(1));
}
